  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

function paintScope() {
  var bs = document.querySelectorAll('#scope .sg');
  for (var i = 0; i < bs.length; i++) {
    bs[i].className = 'sg' + (bs[i].getAttribute('data-scope') === scope ? ' on' : '');
  }
  $('sep').className = 'rowsw' + (scope === 'offline' ? '' : ' hide');
}

// 空名字就整行不显示 —— 之前会孤零零留一个「· 线上」在那里
function paintWho() {
  var txt = charName ? ('当前：' + charName) : '';
  $('who').textContent = txt;
  $('who').className = txt ? '' : 'hide';
}

function show(text) {
  $('msg').textContent = text;
  $('msg').className = text ? '' : 'hide';
  $('list').innerHTML = '';
  $('foot').textContent = '';
}

function load() {
  paintScope();
  return nuo.context().then(function (c) {
    charId = c && c.charId ? String(c.charId) : null;
    charName = (c && c.charName) || '';
    paintWho();
    if (!charId) { state = null; show('先打开一个聊天，再来开关世界书'); return; }
    return nuo.worldbook.config({ charId: charId, scope: scope }).then(function (s) {
      state = s;
      render();
    });
  }).catch(function (e) { show('读取失败：' + (e && e.message || e)); });
}

// 写回：整份 enabledBooks / disabledEntries 一起送
function persist(patch) {
  if (!state || !charId || busy) return Promise.resolve();
  busy = true;
  var body = {
    charId: charId, scope: scope,
    custom: patch.custom === undefined ? state.custom : patch.custom,
    enabledBooks: patch.enabledBooks || state.enabledBooks,
    disabledEntries: patch.disabledEntries || state.disabledEntries
  };
  if (patch.separate !== undefined) body.separate = patch.separate;
  return nuo.worldbook.set(body).then(function () {
    busy = false;
    // 切换「与线上分开」会换掉整份数据源，必须重读而不是就地改
    if (patch.separate !== undefined) return load();
    state.custom = body.custom;
    state.enabledBooks = body.enabledBooks;
    state.disabledEntries = body.disabledEntries;
    render();
  }).catch(function (e) { busy = false; show('保存失败：' + (e && e.message || e)); });
}

function has(arr, v) { return arr.indexOf(String(v)) >= 0; }
function without(arr, v) { return arr.filter(function (x) { return String(x) !== String(v); }); }
function withv(arr, v) { return has(arr, v) ? arr.slice() : arr.concat([String(v)]); }

function render() {
  if (!state) return;
  $('msg').className = 'hide';
  $('custChk').checked = !!state.custom;
  $('sepChk').checked = !!state.separate;
  $('custHint').textContent = state.custom
    ? '勾选的书才生效，词条可单独关'
    : '跟着名册／全局走，要改先打开';
  $('list').className = state.custom ? '' : 'off';

  var q = $('q').value.trim().toLowerCase();
  var html = '';
  var shown = 0, onBooks = 0, onEnts = 0;

  for (var i = 0; i < state.books.length; i++) {
    var b = state.books[i];
    var ents = b.entries || [];
    var on = has(state.enabledBooks, b.id);
    var live = ents.filter(function (e) { return !e.uid || !has(state.disabledEntries, e.uid); });
    if (on) { onBooks++; onEnts += live.length; }

    var hitBook = !q || (b.name || '').toLowerCase().indexOf(q) >= 0;
    var hitEnts = ents.filter(function (e) {
      return !q || hitBook || (e.name || '').toLowerCase().indexOf(q) >= 0
        || (e.keys || '').toLowerCase().indexOf(q) >= 0;
    });
    if (!hitBook && !hitEnts.length) continue;
    shown++;

    var expanded = !!open[b.id] || (!!q && !hitBook);
    html += '<div class="bk"><div class="bkr">'
      + '<button class="arw' + (ents.length ? (expanded ? ' op' : '') : ' no')
      + '" data-arw="' + esc(b.id) + '">&#9654;</button>'
      + '<div class="bkn"><div class="bkt"><em>' + esc(b.name || '未命名') + '</em>'
      + (b.isGlobal ? '<span class="tag g">全局</span>' : '')
      + (b.fromRoster ? '<span class="tag">名册</span>' : '')
      + '</div><div class="bks">'
      + (ents.length ? (on ? (live.length + ' / ' + ents.length + ' 条生效') : (ents.length + ' 条词条')) : '空书')
      + '</div></div>'
      + '<label class="sw"><input type="checkbox" data-book="' + esc(b.id) + '"'
      + (on ? ' checked' : '') + (state.custom ? '' : ' disabled') + '><i></i></label>'
      + '</div>';

    if (expanded && ents.length) {
      var list = (q && !hitBook) ? hitEnts : ents;
      html += '<div class="ents"><div class="all">'
        + '<button data-all="on" data-bid="' + esc(b.id) + '">全开</button>'
        + '<button data-all="off" data-bid="' + esc(b.id) + '">全关</button></div>';
      for (var j = 0; j < list.length; j++) {
        var e = list[j];
        var eon = e.uid ? !has(state.disabledEntries, e.uid) : true;
        html += '<div class="ent"><span class="entn"><b>' + esc(e.name || ('#' + (j + 1)))
          + (e.constant ? ' <span class="tag">常驻</span>' : '') + '</b>'
          + (e.keys ? '<i>' + esc(e.keys) + '</i>' : '') + '</span>'
          + '<label class="sw sm"><input type="checkbox" data-ent="' + esc(e.uid) + '"'
          + ((eon && on) ? ' checked' : '')
          + ((!e.uid || !on || !state.custom) ? ' disabled' : '') + '><i></i></label></div>';
      }
      html += '</div>';
    }
    html += '</div>';
  }

  $('list').innerHTML = shown ? html
    : '<div style="font-size:11.5px;opacity:.6;text-align:center;padding:24px 12px">'
      + (q ? '没有匹配的世界书' : '还没有世界书') + '</div>';
  $('foot').textContent = state.books.length
    ? ('本聊天生效：' + onBooks + ' 本书 · ' + onEnts + ' 条词条')
    : '';
}

// 事件委托：列表整块重绘，逐个绑定会随重绘一起失效
$('list').addEventListener('click', function (ev) {
  var t = ev.target;
  var arw = t.getAttribute && t.getAttribute('data-arw');
  if (arw) { open[arw] = !open[arw]; render(); return; }
  var all = t.getAttribute && t.getAttribute('data-all');
  if (all && state && state.custom) {
    var bid = t.getAttribute('data-bid');
    var bk = state.books.filter(function (b) { return b.id === bid; })[0];
    if (!bk) return;
    var dis = state.disabledEntries.slice();
    (bk.entries || []).forEach(function (e) {
      if (!e.uid) return;
      dis = all === 'on' ? without(dis, e.uid) : withv(dis, e.uid);
    });
    persist({ disabledEntries: dis });
  }
});

$('list').addEventListener('change', function (ev) {
  var t = ev.target;
  if (!state || !state.custom) return;
  var bid = t.getAttribute('data-book');
  if (bid) {
    persist({ enabledBooks: t.checked ? withv(state.enabledBooks, bid) : without(state.enabledBooks, bid) });
    return;
  }
  var uid = t.getAttribute('data-ent');
  if (uid) {
    // 禁用集：关掉才进集合，打开就是从集合里拿掉
    persist({ disabledEntries: t.checked ? without(state.disabledEntries, uid) : withv(state.disabledEntries, uid) });
  }
});

$('custChk').addEventListener('change', function () {
  if (!state) return;
  // 从关到开：以当前继承集合为起点，否则一开就变成「一本书都没勾」
  var next = (this.checked && (!state.enabledBooks || !state.enabledBooks.length))
    ? (state.inherited || []) : state.enabledBooks;
  persist({ custom: this.checked, enabledBooks: next });
});

$('sepChk').addEventListener('change', function () { persist({ separate: this.checked }); });
$('q').addEventListener('input', function () { render(); });
$('refresh').addEventListener('click', function () { load(); });

var sgs = document.querySelectorAll('#scope .sg');
for (var k = 0; k < sgs.length; k++) {
  sgs[k].addEventListener('click', function () {
    scope = this.getAttribute('data-scope');
    try { nuo.storage.set('scope', scope); } catch (e) {}
    load();
  });
}

// 换聊天了就重读 —— 悬浮窗是常驻的，不重读会对着上一个角色开关
nuo.on('chatOpen', function () { load(); });

nuo.storage.get('scope').then(function (v) {
  if (v === 'online' || v === 'offline') scope = v;
}).catch(function () {}).then(function () {
  nuo.ready();
  load();
});

// 小红书链接解析：发出小红书分享 → 聊天里变成笔记卡片，角色读到的是笔记正文。
// 流程：跟着分享短链跳到笔记页 → 读页面里的笔记数据 → 读不到就退回从分享文案里拆标题。
var UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';

function toHttps(u) { return String(u || '').replace(/^http:\/\//i, 'https://'); }

function decodeEntities(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCodePoint(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (m, d) { return String.fromCodePoint(+d); })
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}

function metaOf(html, name) {
  var re = new RegExp('<meta[^>]+(?:name|property)=["\']' + name.replace(/[.:]/g, '\\$&') + '["\'][^>]*>', 'i');
  var tag = html.match(re);
  if (!tag) return '';
  var c = tag[0].match(/content="([^"]*)"/i) || tag[0].match(/content='([^']*)'/i);
  return c ? decodeEntities(c[1]).trim() : '';
}

// 页面里的 window.__INITIAL_STATE__（里面有 undefined，JSON.parse 前先换成 null）
function initialState(html) {
  var key = '__INITIAL_STATE__=';
  var i = html.indexOf(key);
  if (i < 0) return null;
  var start = i + key.length;
  var end = html.indexOf('</script>', start);
  var raw = html.slice(start, end < 0 ? undefined : end).trim().replace(/;\s*$/, '');
  try { return JSON.parse(raw.replace(/:\s*undefined\b/g, ':null').replace(/\[undefined\]/g, '[null]')); } catch (e) { return null; }
}

// 电脑版和手机版页面的数据位置不同，干脆找「长得像一篇笔记」的物件
function findNote(obj, depth) {
  if (!obj || typeof obj !== 'object' || depth > 9) return null;
  if (typeof obj.desc === 'string' && (obj.title != null || obj.displayTitle != null) && (obj.imageList || obj.user)) return obj;
  var keys = Object.keys(obj);
  for (var i = 0; i < keys.length; i++) {
    var hit = findNote(obj[keys[i]], depth + 1);
    if (hit) return hit;
  }
  return null;
}

function firstImage(n) {
  var list = n.imageList || [];
  var im = list[0];
  if (!im) return '';
  if (im.urlDefault) return im.urlDefault;
  if (im.url) return im.url;
  if (im.infoList && im.infoList.length) return im.infoList[im.infoList.length - 1].url || '';
  return im.urlPre || '';
}

// 正文里的 #话题[话题]# 标记还原成 #话题
function cleanDesc(s) {
  return String(s || '')
    .replace(/#([^#\[\n]+)\[[^\]]*\]#/g, '#$1')
    .replace(/[ \t]+\n/g, '\n').replace(/\n[ \t]+/g, '\n')   // 只有空白的行
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// 分享卡里平台那一段：「小红书 - 你的生活兴趣社区」（简繁 / rednote 都有）
var SITE_SEG = /^(?:小红书|小紅書|rednote)/i;

// 分享文案：【标题 - 作者 | 小红书 - 你的生活兴趣社区】 😆 口令 😆 链接 复制本条信息…
// 电脑版：序号 [标题 - 作者| 小紅書 - 你的生活興趣社群] 口令 链接
function fromShareText(text, url) {
  var out = { title: '', author: '', note: '' };
  var rest = String(text || '').split(url).join(' ');
  var box = rest.match(/【([^】]*)】/) || rest.match(/\[([^\[\]]*[|｜][^\[\]]*)\]/);
  if (box && /[|｜]/.test(box[1])) {
    // 标题里自己也可能有「｜」：从最后一个后面接着平台名的「|」切
    var inner = box[1];
    var cut = -1;
    var re = /[|｜]/g, m;
    while ((m = re.exec(inner))) {
      if (SITE_SEG.test(inner.slice(m.index + 1).trim())) cut = m.index;
    }
    var head = (cut >= 0 ? inner.slice(0, cut) : inner.split(/[|｜]/)[0]).trim();
    var dash = head.lastIndexOf(' - ');
    if (dash > 0) { out.title = head.slice(0, dash).trim(); out.author = head.slice(dash + 3).trim(); }
    else out.title = head;
    rest = rest.replace(box[0], ' ');
  }
  rest = rest
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/复制本条信息[\s\S]*$/, ' ')
    // App 分享：「… 链接 直达【小红书】探索笔记全文~」
    .replace(/直达\s*【(?:小红书|小紅書|rednote)】[^\n]*/gi, ' ')
    .replace(/[^\s]*发布了一篇小红书笔记，?快来看吧！?/g, ' ')
    .replace(/😆\s*\S+\s*😆/g, ' ');
  // 电脑版分享卡：去掉口令（一长串字母数字，带数字或多个大写）和开头的序号。
  // 只在认出分享卡格式时才做，免得删掉用户自己打的英文或数字
  if (box) {
    rest = rest
      .replace(/(^|\s)([A-Za-z0-9]{10,24})(?=\s|$)/g, function (all, sp, w) {
        return /\d/.test(w) || (w.match(/[A-Z]/g) || []).length >= 2 ? sp : all;
      })
      .replace(/(^|\s)\d{1,4}(?=\s*$)/, ' ');
  }
  rest = rest.replace(/\s+/g, ' ').trim();
  // 剩下的是用户自己附的话（新版文案没有【】，标题只能等打开笔记页才知道）
  out.note = rest;
  return out;
}

// App 分享文案链接前是「标题 正文开头...」的预览，不是用户自己的话：
// 预览从标题开始就把它连同后面截掉，只留用户写在前面的部分
function userWordsOnly(note, title, desc) {
  var s = String(note || '').trim();
  if (!s) return '';
  var t = String(title || '').trim();
  var i = t ? s.indexOf(t) : -1;
  if (i >= 0) return s.slice(0, i).trim();
  // 没有标题的笔记：预览就是正文开头（结尾带省略号）
  var head = s.replace(/(\.\.\.|…)+\s*$/, '').replace(/\s+/g, '');
  if (head && String(desc || '').replace(/\s+/g, '').indexOf(head) === 0) return '';
  return s;
}

function fmtCount(v) { return v == null || v === '' ? '' : String(v); }

function buildResult(n, share, url) {
  var title = (n.title || n.displayTitle || '').trim() || share.title;
  var author = (n.user && (n.user.nickname || n.user.nickName)) || share.author;
  var desc = cleanDesc(n.desc);
  var tags = (n.tagList || n.hashTag || []).map(function (t) { return t && t.name; }).filter(Boolean);
  var info = n.interactInfo || {};
  var stats = [
    fmtCount(info.likedCount) && '点赞 ' + info.likedCount,
    fmtCount(info.collectedCount) && '收藏 ' + info.collectedCount,
    fmtCount(info.commentCount) && '评论 ' + info.commentCount
  ].filter(Boolean).join(' · ');
  var lines = [];
  lines.push('类型：' + (n.type === 'video' ? '视频笔记' : '图文笔记') + (n.imageList && n.imageList.length > 1 ? '（' + n.imageList.length + ' 张图）' : ''));
  if (desc) lines.push('正文：\n' + desc);
  // 正文末尾常已带着 #话题，全都出现过就不再重复列
  var missingTags = tags.filter(function (x) { return desc.indexOf('#' + x) < 0; });
  if (missingTags.length) lines.push('话题：' + missingTags.map(function (x) { return '#' + x; }).join(' '));
  if (stats) lines.push('互动：' + stats);
  var userNote = userWordsOnly(share.note, title, desc);
  if (userNote) lines.push('附言：' + userNote);
  return {
    title: title,
    desc: desc,
    cover: toHttps(firstImage(n)),
    site: '小红书',
    author: author,
    url: url,
    aiText: lines.join('\n')
  };
}

// 安卓手机浏览器的身份：某些网络下 iPhone 身份会被换成登录页，换一个再试
var UA_ANDROID = 'Mozilla/5.0 (Linux; Android 14; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0 Mobile Safari/537.36';

function isNoteUrl(u) { return /(xiaohongshu|rednote)\.com\/(discovery\/item|explore)\//i.test(u || ''); }
// rednote.com 与 xiaohongshu.com 是同一套站，换个域名有时就放行了
function swapHost(u) {
  if (/rednote\.com/i.test(u)) return u.replace(/rednote\.com/i, 'xiaohongshu.com');
  if (/xiaohongshu\.com/i.test(u)) return u.replace(/xiaohongshu\.com/i, 'rednote.com');
  return '';
}
function pathOf(u) { return String(u || '').replace(/\?.*$/, '').replace(/^https?:\/\//, ''); }

// 打开一次，日志里记清楚：状态码、最后跳到哪、有没有笔记数据
async function tryOpen(u, ua, tag) {
  try {
    var r = await nuo.net.fetch(toHttps(u), { headers: { 'user-agent': ua, 'accept-language': 'zh-CN,zh;q=0.9' } });
    var body = (r && r.body) || '';
    var finalUrl = (r && r.url) || u;
    var note = r && r.ok && !/\/404\b|\/login/i.test(finalUrl) ? findNote(initialState(body), 0) : null;
    nuo.log('[' + tag + '] HTTP ' + (r && r.status) + ' → ' + pathOf(finalUrl) + '，' + body.length + ' 字节，' +
      (note ? '读到笔记' : /\/login/i.test(finalUrl) ? '被跳到登录页' : /\/404\b/.test(finalUrl) ? '笔记无法浏览(404)' : '没有笔记数据'));
    return { note: note, body: note || /\/login|\/404\b/i.test(finalUrl) ? '' : body, finalUrl: finalUrl };
  } catch (e) {
    nuo.log('[' + tag + '] 打开失败：' + (e && (e.code || e.message)) + (e && e.hint ? '（' + e.hint + '）' : ''));
    return { note: null, body: '', finalUrl: u };
  }
}

async function parse(d) {
  var url = d.url;
  var share = fromShareText(d.text, url);
  // 1) 原链接（短链会在这里跟到带 xsec_token 的笔记页）
  var r = await tryOpen(url, UA, '1 原链接');
  var target = isNoteUrl(r.finalUrl) ? r.finalUrl : url;
  var page = r.body;
  // 2) 换域名  3) 换安卓浏览器身份
  if (!r.note && swapHost(target)) r = await tryOpen(swapHost(target), UA, '2 换域名');
  if (!r.note && isNoteUrl(target)) r = await tryOpen(target, UA_ANDROID, '3 换身份');
  // 卡片留用户发的原链接：跳转后的长地址带着分享者的追踪参数
  if (r.note) return buildResult(r.note, share, d.url);
  page = page || r.body;
  if (page) {
    // 没有数据块，退而读 meta
    var t = metaOf(page, 'og:title').replace(/\s*-\s*(?:小红书|小紅書|rednote)\s*$/i, '');
    var ds = metaOf(page, 'description') || metaOf(page, 'og:description');
    if (t || ds) {
      return {
        title: t || share.title, desc: ds, cover: toHttps(metaOf(page, 'og:image')),
        site: '小红书', author: share.author, url: d.url,
        aiText: (ds ? '正文：\n' + ds : '') + (userWordsOnly(share.note, t, ds) ? '\n附言：' + userWordsOnly(share.note, t, ds) : '')
      };
    }
  }
  nuo.log('读不到正文，退回分享标题' + (share.title ? '' : '（连标题也没有，照原文发）'));
  if (!share.title) return null;   // 什么都拿不到：照原文发
  return {
    title: share.title, desc: '', cover: '', site: '小红书', author: share.author, url: d.url,
    aiText: '（没能打开笔记正文，只看得到分享标题）' + (share.note ? '\n附言：' + share.note : '')
  };
}

nuo.link.onParse(parse);
